if (.Platform$OS.type == 'windows') Sys.setlocale('LC_CTYPE','English_United States.utf8')
# UTF-8 report and scientific PNG; no additional package dependencies.
r<-read.delim('outputs/standardized_results.tsv')
flow<-read.delim('outputs/sample_flow.tsv')
cells<-read.delim('outputs/cell_counts.tsv')
raw<-read.delim('outputs/raw_codes_65plus.tsv')
crude<-read.delim('outputs/crude_and_conditional_results.tsv')
esc<-function(x) {x<-gsub('&','&amp;',as.character(x),fixed=TRUE);x<-gsub('<','&lt;',x,fixed=TRUE);gsub('>','&gt;',x,fixed=TRUE)}
tab<-function(x) paste0('<table><thead><tr>',paste0('<th>',esc(names(x)),'</th>',collapse=''),'</tr></thead><tbody>',paste(apply(x,1,function(z)paste0('<tr>',paste0('<td>',esc(z),'</td>',collapse=''),'</tr>')),collapse=''),'</tbody></table>')
fmt<-function(z) sprintf('%.2f [%.2f; %.2f]',100*z$estimate,100*z$lcl,100*z$ucl)
getr<-function(gr,v,kind,anal='main') subset(r,group==gr & outcome==v & estimate_type==kind & analysis==anal)
labels<-c(all='Alle ab 65',stroke='Schlaganfallanamnese',no_stroke='Keine Schlaganfallanamnese')
ends<-c(any='Schluckbeschwerden',severe='Starke Beschwerden',long='Dauer >=180 Tage')
main<-do.call(rbind,lapply(names(labels),function(gr) do.call(rbind,lapply(names(ends),function(v) {
 a<-getr(gr,v,'standardized_2022');b<-getr(gr,v,'standardized_2025');c<-getr(gr,v,'difference_2025_minus_2022')
 data.frame(Gruppe=labels[gr],Endpunkt=ends[v],'2022 % [95%-KI]'=fmt(a),'2025 % [95%-KI]'=fmt(b),'Differenz PP [95%-KI]'=fmt(c),Hinweis=if(c$fragile)'Kleine Alterszellen; explorativ' else '',check.names=FALSE)
}))))
mapping<-data.frame(Variable=c('VSLSWYR_A','VSLSWDIF_A','VSLSWDYS_A','STREV_A','AGEP_A','SEX_A','WTFA_A','PSTRAT / PPSU','INTV_QRT / INTV_QRT2'),
 Bedeutung=c('12-Monats-Schluckbeschwerden','Ausmass der Beschwerden','Beschwerdedauer','Schlaganfallanamnese','Alter','Geschlecht','Finales Jahresgewicht','Oeffentliche Designvariablen','Interviewquartal'),
 Kodierung=c('1 Ja; 2 Nein; 7/8/9 fehlend','1 wenig; 2 viel; 3 dazwischen; 7/8/9 fehlend','1: 1\u20136; 2: 7\u201313; 3: 14\u201329; 4: 30\u201389; 5: 90\u2013179; 6: >=180 Tage; 7/8/9 fehlend','1 Ja; 2 Nein; 7/8/9 fehlend','65\u201384; 85 bedeutet 85+; 97\u201399 fehlend','1 maennlich; 2 weiblich; 7/8/9 fehlend','Positiv; fuer Jahresvergleich unveraendert','Unveraendert ueber Jahre verwenden','2022: 1\u20134; 2025: 1\u20133 und 9 fuer verschobenes Jahresende'),
 Universe=c('Alle Sample Adults','Nur VSLSWYR_A=1','Nur VSLSWYR_A=1','Alle Sample Adults','Alle Sample Adults','Alle Sample Adults','Alle Sample Adults','Alle Faelle','Alle Sample Adults'),
 'Codebook-Seite 2022 / 2025'=c('541 / 489','543 / 491','542 / 490','45 / 44','18 / 21','17 / 19','siehe Identifier','siehe Unit Control File','siehe Unit Control File'),check.names=FALSE)
write.table(mapping,'outputs/variable_mapping.tsv',sep='\t',row.names=FALSE,fileEncoding='UTF-8')
png('outputs/praevalenzen.png',width=1800,height=1100,res=180)
par(mar=c(5,11,4,2),family='sans')
plot(NA,xlim=c(0,27),ylim=c(.5,3.5),yaxt='n',xlab='Altersstandardisierte Praevalenz (%) mit 95%-Konfidenzintervall',ylab='',bty='n',main='Schluckbeschwerden in den vergangenen 12 Monaten')
axis(2,at=3:1,labels=c('Alle ab 65','Schlaganfall-\nanamnese','Keine Schlaganfall-\nanamnese'),las=1,tick=FALSE)
abline(v=seq(0,25,5),col='#e6e6e6',lty=1)
for(i in seq_along(labels)) for(yr in c(2022,2025)) {
 z<-getr(names(labels)[i],'any',paste0('standardized_',yr)); y<-4-i+if(yr==2022).10 else -.10;col<-if(yr==2022)'#28658a' else '#c25c24'
 segments(100*z$lcl,y,100*z$ucl,y,col=col,lwd=2);points(100*z$estimate,y,pch=19,col=col,cex=1.3)
}
legend('bottomright',legend=c('2022','2025'),col=c('#28658a','#c25c24'),pch=19,bty='n')
mtext('Quelle: NCHS, NHIS Public-use-Daten 2022 und 2025; eigene Berechnungen.',side=1,line=3.5,cex=.7)
dev.off()
f<-flow;names(f)<-c('Jahr','Alle Erwachsenen','Alter unbekannt','Alter 65+','Primaer gueltig','Beschwerden ja','Primaer fehlend','Schlaganfall ja','Schlaganfall unbekannt')
st<-subset(cells,group=='stroke' & outcome=='any');st<-st[c('year','agegroup','n','valid','yes','no','missing')]
sens<-do.call(rbind,lapply(names(labels),function(gr)data.frame(Gruppe=labels[gr],'Quartale 1\u20133: Differenz PP [95%-KI]'=fmt(getr(gr,'any','difference_2025_minus_2022','Q1_Q3')),'Extremannahme unten: Differenz PP [95%-KI]'=fmt(getr(gr,'opposite_low','difference_2025_minus_2022','missing_bounds')),'Extremannahme oben: Differenz PP [95%-KI]'=fmt(getr(gr,'opposite_high','difference_2025_minus_2022','missing_bounds')),check.names=FALSE)))
miss<-subset(crude,outcome=='missing_primary');miss<-data.frame(Gruppe=labels[miss$group],Jahr=miss$year,'Fehlend gewichtet % [95%-KI]'=fmt(miss),check.names=FALSE)
links<-paste0('<li><a href="',c('Analyseplan.txt','variable_mapping.tsv','sample_flow.tsv','cell_counts.tsv','raw_codes_65plus.tsv','standardized_results.tsv','crude_and_conditional_results.tsv','weighted_demographics.tsv','design_audit.tsv','validation.txt','README.txt'),'">',c('Analyseplan vor Inferenz','Variablenmapping','Stichprobenfluss','Alle Zellbesetzungen','Alle Rohcodes ab 65','Standardisierte Ergebnisse und Sensitivitaet','Rohe und bedingte Praevalenzen','Gewichtete Demografie','Survey-Design-Audit','Validierung','Reproduktion / Dateibeschreibung'),'</a></li>',collapse='')
html<-paste0('<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NHIS: Machbarkeit und Hauptanalyse</title><style>body{font:16px/1.55 system-ui,sans-serif;color:#20303a;max-width:1200px;margin:40px auto;padding:0 24px}h1,h2{color:#173d53}h2{margin-top:38px}table{border-collapse:collapse;width:100%;font-size:13px;margin:20px 0}td,th{border-bottom:1px solid #d5dce0;padding:9px;text-align:left;vertical-align:top}th{background:#eff4f6}img{max-width:100%}.lead{background:#eef5f8;padding:20px;border-left:5px solid #28658a}.note{color:#5c4b29;background:#fff8e7;padding:16px}a{color:#216389}small{color:#52626c}</style><body>',
 '<h1>Schluckbeschwerden ab 65 Jahren: NHIS 2022 und 2025</h1><p>Machbarkeitsbericht und erste Hauptanalyse \u00b7 Stand 06.11.2026 \u00b7 \u00d6ffentliche Individualdaten \u00b7 Eigenst\u00e4ndige Forschungsberechnung</p>',
 '<div class="lead"><b>Ergebnis:</b> In der Gesamtbev\u00f6lkerung ab 65 Jahren ist ein Anstieg nicht klar belegt: 7,77% auf 8,35%; Differenz +0,57 Prozentpunkte (95%-KI \u22120,40 bis +1,55). In der vorab definierten Schlaganfallgruppe zeigt sich ein exploratives Signal: 14,15% auf 20,43%; +6,27 Prozentpunkte (95%-KI +1,08 bis +11,47). Das ist kein Nachweis einer individuellen Verschlechterung oder eines kausalen Schlaganfalleffekts.</div>',
 '<h2>1. Daten und Vergleichbarkeit</h2><p>Beide Public-use-CSV-Dateien wurden direkt von CDC heruntergeladen. Sie enthalten 27.651 (2022) beziehungsweise 24.215 (2025) Erwachsene; die Gesamtzahlen und die publizierten Ja-H\u00e4ufigkeiten der prim\u00e4ren Variable stimmen mit den Codebooks \u00fcberein. Codebooks, \u00dcbersichten und Survey Descriptions liegen lokal in work/docs, Originalarchive in work/raw. Pr\u00fcfsummen dokumentieren die tats\u00e4chlich verwendeten Dateien.</p>',
 '<p>Die drei Schluckfragen stimmen hinsichtlich Wortlaut, Bezugszeitraum, Frage-ID, Zielgruppe und Antwortkodierung \u00fcberein. Auch die Schlaganfallfrage stimmt \u00fcberein. Erfasst werden berichtete Beschwerden, keine klinisch validierte Dysphagiediagnose. Population: zivile, nicht institutionalisierte US-Bev\u00f6lkerung; Menschen in Pflegeeinrichtungen sind nicht abgedeckt.</p>',
 '<div class="note"><b>Wesentliche Einschr\u00e4nkung 2025:</b> Die Jahresdatei enth\u00e4lt elf Stichprobenmonate mit angepassten Gewichten. Die Erhebung wurde im Oktober/November unterbrochen und Termine wurden verschoben; der Dezemberstichprobenmonat ist nicht enthalten. Zus\u00e4tzlich wurde das Stichprobendesign ge\u00e4ndert. Die CDC erlaubt die gemeinsame Verwendung der \u00f6ffentlichen PSTRAT/PPSU ohne Umkodierung. Gleiche Fragen garantieren dennoch keine vollst\u00e4ndig gleichen Erhebungsbedingungen. Die ver\u00f6ffentlichten R\u00fccklaufquoten 2022 und 2025 haben unterschiedliche Gewichtungsdefinitionen und werden hier nicht unmittelbar verglichen.</div>',
 '<h2>2. Variablenzuordnung</h2>',tab(mapping),
 '<p>Schwere und Dauer: Bei g\u00fcltiger Nein-Antwort auf die Prim\u00e4rfrage wird die Populationsindikatorvariable 0. Bei fehlendem Prim\u00e4rstatus oder fehlender Folgeantwort trotz Ja bleibt sie fehlend. Unter Betroffenen sind Dauer- und Schwereverteilungen separat berechnet; die Rohdatei enth\u00e4lt daf\u00fcr strukturelle Leerwerte au\u00dferhalb der Filtergruppe.</p>',
 '<h2>3. Ungewichtete Machbarkeit</h2>',tab(f),
 '<p>Ungewichtete fehlende Prim\u00e4rantworten: 286/8.771 (3,26%) beziehungsweise 245/8.468 (2,89%). Davon entfallen 279 beziehungsweise 239 auf Code 8 (nicht erhoben/festgestellt), je 4/3 auf Verweigerung und je 3 auf \u201ewei\u00df nicht\u201c. Fehlender Schlaganfallstatus: 18/22. Geschlecht fehlt bei 0/8 Personen ab 65. Unter den 653/689 Betroffenen fehlen Schwereangaben bei 2/1 und Dauerangaben bei 9/18 Personen.</p>',
 '<p>Schlaganfallgruppe nach Alter (ungewichtet):</p>',tab(st),
 '<p>Die prim\u00e4re Interaktionsanalyse erf\u00fcllt die vor der Inferenz festgelegte Zellregel (mindestens 30 g\u00fcltige Beobachtungen, 10 Ereignisse und 10 Nichtereignisse je Jahr\u00d7Schlaganfall\u00d7Alterszelle). Das ist kein Powernachweis. Bei starken Beschwerden liegen in der Schlaganfallgruppe nur 17/25 Ereignisse vor; 2022 sind es in der Alterszelle 85+ nur zwei. Sekund\u00e4re Subgruppenbefunde werden deshalb als fragil markiert.</p>',
 '<h2>4. Analyseverfahren</h2><p>Analyseplan v1 wurde nach dem ungewichteten Machbarkeitscheck, vor den gewichteten Endpunktsch\u00e4tzungen gespeichert und mit SHA-256 fixiert. Keine externe Pr\u00e4registrierung. Verwendet: R 4.6.0, survey 4.5, Taylor-Linearisierung, WTFA_A, PSTRAT und PPSU. Das Design wurde auf allen Erwachsenen aufgebaut; Alter und Schlaganfall wurden als Dom\u00e4nen analysiert. Beide Jahre sind angeh\u00e4ngt, Jahresgewichte und \u00f6ffentliche Designkennungen unver\u00e4ndert. Die vollst\u00e4ndige Kovarianzmatrix geht in Jahres- und Interaktionskontraste ein.</p>',
 '<p>Direkte Altersstandardisierung auf die US-Standardpopulation 2000, Gruppen 65\u201374, 75\u201384 und 85+, innerhalb 65+ normiert. Pr\u00e4valenz-KI auf Logit-Skala mittels Delta-Methode und t-Quantilen; Differenz-KI als lineare Kontraste. Prim\u00e4rer Test: Jahresdifferenz aller Personen 65+. Sekund\u00e4re Endpunkte, Subgruppen und Interaktion sind explorativ, ohne Multiplizit\u00e4tskorrektur. Keine Geschlechtsstandardisierung. Ausf\u00fchrliche Entscheidungen im verlinkten Analyseplan.</p>',
 '<h2>5. Altersstandardisierte Ergebnisse</h2><img src="praevalenzen.png" alt="Altersstandardisierte Pr\u00e4valenzen mit Konfidenzintervallen f\u00fcr beide Jahre und Schlaganfallgruppen">',tab(main),
 '<p>Die sekund\u00e4ren Pr\u00e4valenzen beziehen sich auf die jeweilige gesamte Bev\u00f6lkerungsgruppe, nicht nur auf Personen mit Beschwerden. PP = Prozentpunkte. Die breite Unsicherheit fragiler Subgruppen darf nicht als Gleichheit oder fehlende klinische Relevanz interpretiert werden.</p>',
 '<p>Explorative additive Interaktion: Der Jahresanstieg ist in der Schlaganfallgruppe um <b>6,05 Prozentpunkte</b> gr\u00f6\u00dfer als ohne Schlaganfallanamnese (95%-KI 0,77 bis 11,33; p=0,025). Das ist eine Differenz von Jahresdifferenzen auf Pr\u00e4valenzskala, kein kausales Difference-in-differences-Design. Der prim\u00e4re Gesamtvergleich ergibt p=0,248.</p>',
 '<h2>6. Fehlende Antworten und Sensitivit\u00e4t</h2>',tab(miss),tab(sens),
 '<p>Quartale 1\u20133 ergeben eine \u00e4hnliche Richtung; der Schlaganfallvergleich liegt nur knapp oberhalb der Nullgrenze. Die Jahresgewichte wurden f\u00fcr diese explorative Dom\u00e4nenanalyse nicht speziell neu kalibriert. Sie ersetzt keinen vollwertigen saisonbereinigten Vergleich.</p>',
 '<p>\u201eExtremannahme unten\u201c setzt alle fehlenden Prim\u00e4rantworten 2022 auf Ja und 2025 auf Nein; \u201eoben\u201c umgekehrt. Diese Szenarien sind keine plausibilit\u00e4tsgewichteten Imputationen. F\u00fcr die Schlaganfallgruppe umfasst das untere Szenario trotz positiver Punktsch\u00e4tzung mit seinem KI die Null. Der Anstiegsbefund ist daher gegen\u00fcber beliebig unterschiedlichem Item-Nonresponse nicht statistisch robust. Alters- und Schlaganfallstatus-Unbekannte sind durch diese Grenzen nicht abgedeckt; vollst\u00e4ndiger Interview-Nonresponse ebenfalls nicht.</p>',
 '<h2>7. Qualit\u00e4tssicherung und Grenzen</h2><p>Ein zweiter Rechenweg \u00fcber ein ges\u00e4ttigtes surveygewichtetes lineares Modell reproduziert Alterszellsch\u00e4tzer und deren vollst\u00e4ndige Kovarianzmatrizen bis auf numerische Rundung (maximale Abweichungen unter 10\u207b\u2079). Zus\u00e4tzlich wurden Standardisierungswerte manuell aus gewichteten Altersgruppenmitteln gepr\u00fcft. Identifikatoren, Gewichte, Pflichtvariablen und Filterlogik bestehen die automatischen Pr\u00fcfungen.</p>',
 '<p>Verbleibend: wiederholte Querschnitte statt Verlauf; Selbst-/Proxy-Berichte; kein Zeitpunkt des Schlaganfalls und keine \u00e4tiologische Zuordnung; Unterschiede in Interviewmodus, Teilnahme und Erhebungsorganisation; Ausschluss institutionalisierter Personen; keine Garantie, dass die Gewichte den Nonresponse ausreichend korrigieren. Standardisierung kontrolliert nur die gew\u00e4hlten Altersgruppen. Die Pr\u00e4zisionsmarkierungen sind Projektregeln und ersetzen noch keine vollst\u00e4ndige Pr\u00fcfung nach NCHS Data Presentation Standards. Tabellen sind ein Forschungszwischenstand, keine freigegebenen Publikationstabellen.</p>',
 '<p><b>Machbarkeitsentscheidung:</b> Die prim\u00e4re Jahresvergleichsanalyse ist technisch und hinsichtlich Zellbesetzung durchf\u00fchrbar. Der Gesamtbefund st\u00fctzt keine pauschale Zunahme. Die vorab definierte Schlaganfallgruppe liefert ein vertiefungsw\u00fcrdiges, exploratives Signal; kleine sekund\u00e4re Zellen und Erhebungsunterschiede bleiben entscheidende Grenzen.</p>',
 '<h2>8. Dateien und Reproduktion</h2><ul>',links,'</ul><p>Quellcode: 00_setup.R \u2192 01_prepare.R \u2192 02_analyse.R \u2192 03_validate.R \u2192 04_report.R. Ausf\u00fchrung vom Projektwurzelverzeichnis; Ergebnisse unter outputs, Daten und lokale Bibliothek unter work. Tabellenwerte in TSV sind Anteile (0\u20131); im Bericht werden Prozent bzw. Prozentpunkte angezeigt.</p>',
 '<h2>Offizielle Quellen</h2><ul><li><a href="https://www.cdc.gov/nchs/nhis/documentation/2022-nhis.html">CDC NHIS 2022 \u2013 Daten und Dokumentation</a></li><li><a href="https://www.cdc.gov/nchs/nhis/documentation/2025-nhis.html">CDC NHIS 2025 \u2013 Daten und Dokumentation</a></li><li><a href="https://ftp.cdc.gov/pub/Health_Statistics/NCHS/Dataset_Documentation/NHIS/2022/adult-codebook.pdf">2022 Adult Codebook, 05.06.2023, insbesondere S.541\u2013543</a></li><li><a href="https://ftp.cdc.gov/pub/Health_Statistics/NCHS/Dataset_Documentation/NHIS/2025/adult-codebook.pdf">2025 Adult Codebook, 29.07.2026, insbesondere S.489\u2013491</a></li><li><a href="https://ftp.cdc.gov/pub/Health_Statistics/NCHS/Dataset_Documentation/NHIS/2025/srvydesc-508.pdf">2025 Survey Description, insbesondere S.10, 13\u201316, 35, 47\u201350</a></li><li><a href="https://www.cdc.gov/nchs/hus/sources-definitions/age-adjustment.htm">CDC: Altersstandardisierung, Tabelle I</a></li></ul><p><small>Datenquelle: National Center for Health Statistics, National Health Interview Survey, 2022 und 2025. Analysen, Interpretationen und Schlussfolgerungen sind eigene Berechnungen und nicht Positionen des NCHS. Keine externe Einreichung oder Kontaktaufnahme.</small></p></body></html>')
writeLines(enc2utf8(html),'outputs/Machbarkeitsbericht.html',useBytes=TRUE)
